  1	#version 450
  2	
  3	#extension GL_KHR_shader_subgroup_basic : require
  4	#extension GL_KHR_shader_subgroup_arithmetic : require
  5	#extension GL_EXT_shader_16bit_storage : require
  6	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
  7	#extension GL_EXT_control_flow_attributes : require
  8	
  9	// The routing permutation and the tile schedule it implies (LLM.md L5b).
 10	//
 11	// A counting sort over the 512 experts: histogram, exclusive prefix sum,
 12	// scatter. It is one workgroup because the whole input is `tokens * used`
 13	// integers — 5120 at a 512-token ubatch, 40 960 at the 4 k fixture — and 97%
 14	// of this block's time is in the two GEMMs behind it.
 15	//
 16	// **L5a-4 is why the schedule is a list and not a grid.** At a 512-token
 17	// ubatch only **274 of 512 experts are touched**, one of them takes **484 of
 18	// the 512 tokens** and the other 273 have fewer than 19: a workgroup per
 19	// expert has a 26x load imbalance and a grid of (experts x fixed row blocks)
 20	// is almost entirely empty. So this kernel emits one record per (expert, row
 21	// block) that has rows — `tileCount` of them — and the GEMM dispatches a
 22	// static upper bound of `ceil(tokens*used/BM) + nExperts` row blocks, every
 23	// one past `tileCount` returning before it reads anything.
 24	//
 25	// **Each expert's rows are padded up to `pc.gemmN`, and that padding is what
 26	// buys the GEMM its epilogue.** A cooperative-matrix store covers sixteen
 27	// rows at once and cannot be masked, so a tile whose expert runs out of rows
 28	// part-way through would have to stage its accumulators in LDS and copy them
 29	// out under a bound — which is 8-16 KB of LDS on a kernel whose occupancy is
 30	// already one wave a SIMD. Rounding every expert's range up instead means a
 31	// tile's rows are *always* that expert's, the store goes straight out, and
 32	// the padding rows are named by a **sentinel** permutation entry pointing at
 33	// a token index one past the batch, whose activation row is zero. The
 34	// alignment is the wider of the two modes' row blocks, so both tile lists
 35	// divide it exactly and the two ladders stay independent.
 36	//
 37	// Two more things the layout does. The row a permutation entry names is
 38	// `token * (used + 1) + slot`, not the token — so the slot stride carries the
 39	// shared expert's row as its last element. And the **inverse** permutation is
 40	// written beside it, because the down projection's output lands in
 41	// permutation order and the combine has to find a token's eleven
 42	// contributions again; the alternative is a scattered store, and a scattered
 43	// store is the LDS round trip this file exists to avoid.
 44	//
 45	// The order of rows *within* an expert is whatever the scatter's atomics
 46	// give, and nothing depends on it: every row is independent and the combine
 47	// sums by (token, slot).
 48	
 49	#include "llm_common.glsl"
 50	
 51	#define WG 256
 52	#define MAX_EXPERTS 512
 53	
 54	layout(local_size_x = WG) in;
 55	
 56	shared uint shCnt[MAX_EXPERTS];
 57	shared uint shWave[WG / 64];
 58	shared uint shTotal;
 59	
 60	void main() {
 61	    uint tid = gl_LocalInvocationID.x;
 62	    uint nE = pc.gemmK;          // the expert count
 63	    uint used = MOE_USED;
 64	    uint slots = used + 1u;
 65	    uint pairs = pc.tokens * used;
 66	    uint bm = pc.gemmM;          // the row block this tile list is cut to
 67	    uint pad = pc.gemmN;         // the row alignment both lists share
 68	    uint sg = tid / 64u;
 69	
 70	    // The shared expert is one group of the same grouped GEMM and it takes
 71	    // the front of the row space: it runs for every token, so its rows are
 72	    // the identity and the host writes them. The routed experts start behind
 73	    // it.
 74	    uint reserve = ((pc.tokens + pad - 1u) / pad) * pad;
 75	
 76	    // The four per-expert arrays the counting sort keeps. They sit behind the
 77	    // permutation, which the host sizes for the widest rung, so where they
 78	    // start is the host's to say — `moeBOff2`, which in a GEMM dispatch is
 79	    // the second quantised matrix and here has no matrix to name.
 80	    uint book = pc.moeBOff2;
 81	    uint counts = book;
 82	    uint offsets = book + nE;
 83	    uint cursor = book + 2u * nE;
 84	    uint tileBase = book + 3u * nE;
 85	    uint topk = pc.moeWeightOff + pc.tokens * slots;
 86	    uint invPerm = topk + pairs;
 87	
 88	    for (uint e = tid; e < nE; e += WG) {
 89	        actu[counts + e] = 0u;
 90	    }
 91	    barrier();
 92	
 93	    // ---- The histogram.
 94	    for (uint p = tid; p < pairs; p += WG) {
 95	        atomicAdd(actu[counts + actu[topk + p]], 1u);
 96	    }
 97	    barrier();
 98	
 99	    // ---- Two exclusive prefix sums over the experts, in the same shape: one
100	    // over the padded counts, which is where an expert's rows start, and one
101	    // over padded/BM, which is where its tile records start. A subgroup scan
102	    // per wave, the wave totals carried across, and a carry across the
103	    // chunks — because nE is 512 and the workgroup is 256.
104	    uint carryRows = reserve;
105	    uint carryTiles = 0u;
106	    for (uint c0 = 0u; c0 < MAX_EXPERTS; c0 += WG) {
107	        uint e = c0 + tid;
108	        uint cnt = (e < nE) ? actu[counts + e] : 0u;
109	        shCnt[e] = cnt;
110	        uint padded = ((cnt + pad - 1u) / pad) * pad;
111	        uint nt = padded / bm;
112	
113	        uint rowTot = subgroupAdd(padded);
114	        uint rowEx = subgroupExclusiveAdd(padded);
115	        uint tileTot = subgroupAdd(nt);
116	        uint tileEx = subgroupExclusiveAdd(nt);
117	        if (subgroupElect()) {
118	            shWave[sg] = rowTot;
119	        }
120	        barrier();
121	        uint rowBefore = 0u, rowAll = 0u;
122	        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
123	            rowAll += shWave[w];
124	            if (w < sg) {
125	                rowBefore += shWave[w];
126	            }
127	        }
128	        barrier();
129	        if (subgroupElect()) {
130	            shWave[sg] = tileTot;
131	        }
132	        barrier();
133	        uint tileBefore = 0u, tileAll = 0u;
134	        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
135	            tileAll += shWave[w];
136	            if (w < sg) {
137	                tileBefore += shWave[w];
138	            }
139	        }
140	        barrier();
141	
142	        if (e < nE) {
143	            uint off = carryRows + rowBefore + rowEx;
144	            actu[offsets + e] = off;
145	            actu[cursor + e] = off;
146	            actu[tileBase + e] = carryTiles + tileBefore + tileEx;
147	        }
148	        carryRows += rowAll;
149	        carryTiles += tileAll;
150	    }
151	    if (tid == 0u) {
152	        actu[pc.moeTileOff] = carryTiles;
153	        actu[pc.moeTileOff + 1u] = carryRows;
154	        shTotal = carryRows;
155	    }
156	    barrier();
157	
158	    // ---- Every routed row starts as the sentinel: a (token, slot) pair one
159	    // token past the batch, whose activation row is a zero pad. What the
160	    // scatter does not overwrite is padding, and padding has to compute
161	    // something finite rather than whatever the arena last held.
162	    uint sentinel = pc.tokens * slots;
163	    for (uint r = reserve + tid; r < shTotal; r += WG) {
164	        actu[pc.moePermOff + r] = sentinel;
165	    }
166	    barrier();
167	
168	    // ---- The scatter, and the inverse beside it. `p` is (token, slot)
169	    // flattened by `used`; what lands in the permutation is the same pair
170	    // flattened by `used + 1`, so the shared expert's slot is already spoken
171	    // for.
172	    for (uint p = tid; p < pairs; p += WG) {
173	        uint e = actu[topk + p];
174	        uint idx = atomicAdd(actu[cursor + e], 1u);
175	        uint tok = p / used;
176	        uint k = p - tok * used;
177	        actu[pc.moePermOff + idx] = tok * slots + k;
178	        actu[invPerm + tok * slots + k] = idx;
179	    }
180	
181	    // ---- The tile records: expert, first row, and the row block, which is
182	    // now always full because the range was padded to it.
183	    for (uint e = tid; e < nE; e += WG) {
184	        uint cnt = shCnt[e];
185	        uint padded = ((cnt + pad - 1u) / pad) * pad;
186	        uint off = actu[offsets + e];
187	        uint tb = actu[tileBase + e];
188	        for (uint mb = 0u; mb * bm < padded; ++mb) {
189	            uint rec = pc.moeTileOff + 2u + 3u * (tb + mb);
190	            actu[rec] = e;
191	            actu[rec + 1u] = off + mb * bm;
192	            actu[rec + 2u] = bm;
193	        }
194	    }
195	}

