#ifndef KSLABS
#define KSLABS 16
#endif
// The down GEMM's column block, and the only thing this kernel needs to know
// about that one: L8b's Q8 split is the block containing `inject`, so both
// kernels round `pc.lowRank` down to it. Compiled in for the reason KSLABS is.
#ifndef DOWN_BN
#define DOWN_BN 48
#endif

#define TILE 16
#define WAVE 64

layout(local_size_x = WAVE) in;

float sigmoidf(float x) { return 1.0 / (1.0 + exp(-x)); }

void main() {
#if MODE == 0
    uint slab = gl_WorkGroupID.x;                // which stripe of K
    uint nt = gl_WorkGroupID.y;                  // which 16 output columns
    uint ktiles = pc.gemmK / TILE;               // 640
    uint perSlab = ktiles / KSLABS;              // 40
    uint kt0 = slab * perSlab;

    uint lane = gl_LocalInvocationID.x;
    uint col = lane % TILE;                      // the output column this lane owns
    uint sub = lane / TILE;                      // which of the four tiles of a step
    uint xbase = pc.xnOff + kt0 * TILE;

#ifdef Q8B
    // The fused down projection is int8 up to the column block that holds
    // `inject`, and halves from there on: the same split llm_gemm.comp's
    // MODE 0 arm derives, from the same `pc.lowRank`, because the two read
    // one staged bank. DOWN_BN is that kernel's column block and the host
    // checks the two agree — a mismatch would read the wrong plane, not run
    // slowly.
    uint qSplit = (pc.lowRank / DOWN_BN) * DOWN_BN;
    bool tail = nt * TILE >= qSplit;
    // The tiles as words and the scale plane as halves, exactly as the GEMM
    // derives them: a matrix is gemmN x gemmK bytes and the plane follows it.
    uint qbase = (pc.bOff >> 2) + (nt * ktiles + kt0) * 64u + lane * 4u;
    uint sbase = ((pc.bOff + pc.gemmN * pc.gemmK) >> 1) + nt * (pc.gemmK >> 5) * TILE + col;
    // The tail's own tiling, numbered from the split.
    uint wbase = pc.gateOff + ((nt - qSplit / TILE) * ktiles + kt0) * (TILE * TILE);

