 7	// `ffn_out` — the ten routed contributions and the shared expert's, weighted
 8	// and summed (LLM.md L5b).
 9	//
10	// It exists because the down projection cannot accumulate in place: a token's
11	// ten experts are ten different tiles of the grouped GEMM, so without a float
12	// atomic each writes its own row and something has to add them up.
13	//
14	// It carries the **routing weights** for a reason that is not about
15	// arithmetic. The down projection's rows come out in permutation order, which
16	// is what lets it store whole cooperative-matrix fragments straight to global
17	// instead of scattering them a row at a time through LDS; but in that order a
18	// workgroup does not know which (token, slot) a row is without reading the
19	// permutation per row, and the weight would have to be applied per row
20	// anyway. Here the weight is a scalar per row of a read that happens once
21	// regardless. So `ffn_moe_weighted` is still never a tensor, and the store it
22	// would have ridden on stays a fragment store.
23	//
24	// The order is the reference's: the ten in slot order, then
25	// `ffn_shexp_gated`, which is the chain of adds `build_layer_ffn` emits and
26	// the order `moe.go`'s CPU reference sums in.
27	
28	#include "llm_common.glsl"
29	
30	#define WG 256
31	
32	layout(local_size_x = WG) in;
33	
34	void main() {
35	    uint t = gl_WorkGroupID.x;
36	    if (t >= pc.tokens) {
37	        return;
38	    }
39	    uint slots = MOE_USED + 1u;
40	    // The inverse permutation sits behind the weights and the top-k, all
41	    // three indexed by the same (token, slot).
42	    uint invPerm = pc.moeWeightOff + pc.tokens * slots + pc.tokens * MOE_USED;
43	    uint dst = pc.outOff + t * pc.nEmbd;
44	    for (uint j = gl_LocalInvocationID.x; j < pc.nEmbd; j += WG) {
45	        float s = 0.0;
46	        for (uint k = 0u; k < slots; ++k) {
47	            uint row = actu[invPerm + t * slots + k];
48	            s += act[pc.gatedOff + row * pc.nEmbd + j] * act[pc.moeWeightOff + t * slots + k];
49	        }
50	        act[dst + j] = s;
51	    }
52	}

